values
  ('a9000000-0000-4000-8000-000000000001', null, 'Dallas Animal Services', 'The City of Dallas municipal animal shelter, caring for thousands of dogs and cats each year with the help of a large volunteer base.', 'https://dallascityhall.com', 'https://www.google.com/s2/favicons?domain=dallascityhall.com&sz=128', 'animals', array['recurring'], false, false, 15, 'United States', 'TX', 'Dallas', true, true, 'ongoing', false),
  ('a9000000-0000-4000-8000-000000000002', null, 'SPCA of Texas', 'A leading animal welfare organization in North Texas, running shelters, adoption events, and youth-focused volunteer programs.', 'https://spca.org', 'https://www.google.com/s2/favicons?domain=spca.org&sz=128', 'animals', array['family friendly', 'good for crews'], false, false, 10, 'United States', 'TX', 'Dallas', true, true, 'both', false),
  ('a9000000-0000-4000-8000-000000000003', null, 'Dallas Zoo', 'One of the largest zoos in Texas, running the Zoo Crew program to give teens hands-on experience across nearly every part of zoo operations.', 'https://www.dallaszoo.com', 'https://www.google.com/s2/favicons?domain=www.dallaszoo.com&sz=128', 'animals', array['leadership role'], false, false, 13, 'United States', 'TX', 'Dallas', true, true, 'ongoing', false),
  ('a9000000-0000-4000-8000-000000000004', null, 'North Texas Food Bank', 'The largest hunger-relief organization in North Texas, distributing food across the region through its Plano distribution center and partner network.', 'https://volunteer.ntfb.org', 'https://www.google.com/s2/favicons?domain=volunteer.ntfb.org&sz=128', 'food', array['good for crews', 'family friendly'], false, false, 10, 'United States', 'TX', 'Dallas', true, true, 'both', false),
  ('a9000000-0000-4000-8000-000000000005', null, 'Communities In Schools of the Dallas Region', 'A nonprofit placing support staff and volunteers directly inside Dallas-area schools to help students stay on track academically and personally.', 'https://cisdallas.org', 'https://www.google.com/s2/favicons?domain=cisdallas.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 14, 'United States', 'TX', 'Dallas', true, true, 'ongoing', false),
  ('a9000000-0000-4000-8000-000000000006', null, 'Boys and Girls Clubs of Greater Dallas', 'A youth development organization running after-school and summer clubs across Dallas that give kids a safe place to learn and grow.', 'https://www.bgcdallas.org', 'https://www.google.com/s2/favicons?domain=www.bgcdallas.org&sz=128', 'community', array['recurring', 'leadership role'], false, false, 14, 'United States', 'TX', 'Dallas', true, true, 'ongoing', false),
  ('a9000000-0000-4000-8000-000000000007', null, 'United to Learn', 'A Dallas nonprofit connecting volunteer tutors with students who need extra one-on-one academic support during the school day.', 'https://unitedtolearn.org', 'https://www.google.com/s2/favicons?domain=unitedtolearn.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 14, 'United States', 'TX', 'Dallas', true, true, 'ongoing', false),
  ('a9000000-0000-4000-8000-000000000008', null, 'Voice of Hope Ministries', 'A Dallas nonprofit running the High Impact Tutoring program inside Dallas ISD schools to close academic gaps for students who need it most.', 'https://voiceofhope.org', 'https://www.google.com/s2/favicons?domain=voiceofhope.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 16, 'United States', 'TX', 'Dallas', true, true, 'ongoing', false),
  ('a9000000-0000-4000-8000-000000000009', null, 'INSPIRE Dallas', 'The Dallas-area program of Special Olympics Texas, providing sports training and mentorship opportunities for athletes with intellectual disabilities.', 'https://inspiretx.org', 'https://www.google.com/s2/favicons?domain=inspiretx.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 15, 'United States', 'TX', 'Dallas', true, true, 'both', false),
  ('a9000000-0000-4000-8000-000000000010', null, 'Dallas Youth Sports Association', 'A youth sports organization running leagues and programs across Dallas, relying on volunteers to coach and support local teams.', 'https://www.dallasyouthsports.org', 'https://www.google.com/s2/favicons?domain=www.dallasyouthsports.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 14, 'United States', 'TX', 'Dallas', true, true, 'ongoing', false),
  ('a9000000-0000-4000-8000-000000000011', null, 'Texas Health Resources', 'A major North Texas hospital network running a structured Junior Volunteer program each summer across its many campus locations.', 'https://www.texashealth.org', 'https://www.google.com/s2/favicons?domain=www.texashealth.org&sz=128', 'medicine', array['counts for school hours'], false, false, 16, 'United States', 'TX', 'Dallas', true, true, 'one-time', false),
  ('a9000000-0000-4000-8000-000000000012', null, 'Trinity River Audubon Center', 'A 120-acre nature preserve and Audubon center built on reclaimed land along the Trinity River, offering nearly five miles of trails and habitat restoration projects.', 'https://trinityriver.audubon.org', 'https://www.google.com/s2/favicons?domain=trinityriver.audubon.org&sz=128', 'environment', array['outdoors', 'good for crews'], false, false, 12, 'United States', 'TX', 'Dallas', true, true, 'both', false)
