insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('aa000000-0000-4000-8000-000000000001', 'a9000000-0000-4000-8000-000000000001', 'Volunteer with Dallas Animal Services', 'animals', 'Volunteers 15 and up can serve independently after an orientation, taking on tasks like dog walking, cat socializing, and event support, while ages 13-15 can join animal handling roles alongside a parent or guardian. It is a solid option if you want hands-on shelter experience run directly by the city.', array['recurring'], 15, false, false, true, '2-3 hrs', 'https://dallascityhall.com/departments/dallas-animal-services/Pages/Volunteer.aspx', 'https://dallascityhall.com/departments/dallas-animal-services/Pages/Volunteer.aspx', '2026-01-01T00:00:00Z', 'Dallas', 'TX'),
  ('aa000000-0000-4000-8000-000000000002', 'a9000000-0000-4000-8000-000000000002', 'Volunteer with the SPCA of Texas', 'animals', 'Youth ages 10 and up can volunteer with their families, while solo volunteers generally need to be 15 or older unless part of a youth-focused nonprofit group, in which case chaperones are required for younger members. It is a great option for a family or club project.', array['family friendly', 'good for crews'], 10, false, false, true, '2-3 hrs', 'https://spca.org/support-us/volunteer/group-volunteer-opportunities/', 'https://spca.org/support-us/volunteer/group-volunteer-opportunities/', '2026-01-01T00:00:00Z', 'Dallas', 'TX'),
  ('aa000000-0000-4000-8000-000000000003', 'a9000000-0000-4000-8000-000000000003', 'Join the Dallas Zoo Crew', 'animals', 'Teens 13 to 17 rotate through departments including guest services, special events, education, and animal care, combining in-person zoo days with virtual training. Note there is a $200 program fee, and applicants must commit to attending all scheduled sessions.', array['leadership role'], 13, false, false, true, 'Seasonal program', 'https://www.dallaszoo.com/zoo-crew/', 'https://www.dallaszoo.com/zoo-crew/', '2026-01-01T00:00:00Z', 'Dallas', 'TX'),
  ('aa000000-0000-4000-8000-000000000004', 'a9000000-0000-4000-8000-000000000004', 'Volunteer at the North Texas Food Bank', 'food', 'Volunteers pack and box food in an assembly-line setting, with some family volunteer days welcoming kids as young as 10 to help sort and pack alongside a parent. Shifts include weekday Pack and Box sessions and weekend Cold Sorting on Fridays and Saturdays.', array['good for crews', 'family friendly'], 10, false, false, true, '2-3 hrs', 'https://volunteer.ntfb.org/', 'https://volunteer.ntfb.org/', '2026-01-01T00:00:00Z', 'Dallas', 'TX'),
  ('aa000000-0000-4000-8000-000000000005', 'a9000000-0000-4000-8000-000000000005', 'Volunteer with Communities In Schools Dallas', 'education', 'Volunteers tutor, mentor, and assist small groups of students during school hours, with activities ranging from reading practice to test prep to career days. It is a strong option if you want to see your service connected to a specific school campus.', array['recurring', 'counts for school hours'], 14, false, false, true, '1-2 hrs / week', 'https://cisdallas.org/volunteer/', 'https://cisdallas.org/volunteer/', '2026-01-01T00:00:00Z', 'Dallas', 'TX'),
  ('aa000000-0000-4000-8000-000000000006', 'a9000000-0000-4000-8000-000000000006', 'Volunteer at Boys and Girls Clubs of Greater Dallas', 'community', 'Teens 14 and up can tutor and mentor younger kids, or help lead sports and art programs at local club locations. It is a great way to build mentoring experience while staying involved in a consistent community space.', array['recurring', 'leadership role'], 14, false, false, true, '1-2 hrs / week', 'https://www.bgcdallas.org/volunteer/', 'https://www.bgcdallas.org/volunteer/', '2026-01-01T00:00:00Z', 'Dallas', 'TX'),
  ('aa000000-0000-4000-8000-000000000007', 'a9000000-0000-4000-8000-000000000007', 'Tutor with United to Learn', 'education', 'Students 14 and up can sign up for structured one-on-one tutoring sessions, available weekdays from 8 AM to 3 PM either in person or online. The flexible online option is convenient if you cannot easily get to a school site during the day.', array['recurring', 'counts for school hours'], 14, false, false, true, 'Flexible', 'https://unitedtolearn.org/volunteer-in-dallas/', 'https://unitedtolearn.org/volunteer-in-dallas/', '2026-01-01T00:00:00Z', 'Dallas', 'TX'),
  ('aa000000-0000-4000-8000-000000000008', 'a9000000-0000-4000-8000-000000000008', 'Tutor with Voice of Hope Tutor Plus', 'education', 'Volunteers provide High Impact Tutoring support to Dallas ISD students, working directly with the program team to build consistent, measurable academic progress. It is a good fit if you want your tutoring tied to a structured, school-district-backed program.', array['recurring', 'counts for school hours'], 16, false, false, true, 'Flexible', 'https://voiceofhope.org/tutor-plus/', 'https://voiceofhope.org/tutor-plus/', '2026-01-01T00:00:00Z', 'Dallas', 'TX'),
  ('aa000000-0000-4000-8000-000000000009', 'a9000000-0000-4000-8000-000000000009', 'Volunteer with INSPIRE Dallas', 'sports', 'Volunteers as young as 15 can take on most roles, from event support to mentorship and buddy programs, with head coach positions requiring volunteers to be 18 or older. It is a meaningful entry point into coaching if you are willing to work your way up to a lead role.', array['recurring', 'leadership role'], 15, false, false, true, '1-2 hrs / week', 'https://inspiretx.org/join/', 'https://inspiretx.org/join/', '2026-01-01T00:00:00Z', 'Dallas', 'TX'),
  ('aa000000-0000-4000-8000-000000000010', 'a9000000-0000-4000-8000-000000000010', 'Volunteer with Dallas Youth Sports', 'sports', 'Volunteers help coach youth sports teams, run practices, and support league events across the city. It is a good option if you already play a sport and want to pass that experience on to younger kids.', array['recurring', 'leadership role'], 14, false, false, true, 'Varies', 'https://www.dallasyouthsports.org/Default.aspx?tabid=1251920', 'https://www.dallasyouthsports.org/Default.aspx?tabid=1251920', '2026-01-01T00:00:00Z', 'Dallas', 'TX'),
  ('aa000000-0000-4000-8000-000000000011', 'a9000000-0000-4000-8000-000000000011', 'Join the Texas Health Junior Volunteer Program', 'medicine', 'Students 16 to 18 complete a set number of volunteer hours over several weeks in non-clinical roles across patient care areas and business operations. Program length and hour requirements vary by campus, so check your nearest Texas Health facility for exact details.', array['counts for school hours'], 16, false, false, true, '48-64 hrs total', 'https://www.texashealth.org/Volunteer/Junior-Volunteer', 'https://www.texashealth.org/Volunteer/Junior-Volunteer', '2026-01-01T00:00:00Z', 'Dallas', 'TX'),
  ('aa000000-0000-4000-8000-000000000012', 'a9000000-0000-4000-8000-000000000012', 'Volunteer at Trinity River Audubon Center', 'environment', 'Volunteers clear and expand trails, remove invasive plants, and help with large-scale native plantings, with training and supplies provided by Audubon staff. Volunteers also get free admission and discounts at the nature store as a thank-you.', array['outdoors', 'good for crews'], 12, false, false, true, '2-3 hrs', 'https://trinityriver.audubon.org/volunteering/volunteer-us', 'https://trinityriver.audubon.org/volunteering/volunteer-us', '2026-01-01T00:00:00Z', 'Dallas', 'TX')
on conflict (id) do nothing;

-- Migration 016: 11 real, local Philadelphia organizations,
