values
  ('ad000000-0000-4000-8000-000000000001', null, 'Seattle Food Committee', 'A Seattle-based hunger-relief network coordinating food distribution and volunteer support across the city.', 'https://www.seattlefoodcommittee.org', 'https://www.google.com/s2/favicons?domain=www.seattlefoodcommittee.org&sz=128', 'food', array['good for crews'], false, false, 14, 'United States', 'WA', 'Seattle', true, true, 'both', false),
  ('ad000000-0000-4000-8000-000000000002', null, 'Seattle Humane', 'A major Seattle-area animal welfare organization running shelter, adoption, and youth education programs.', 'https://www.seattlehumane.org', 'https://www.google.com/s2/favicons?domain=www.seattlehumane.org&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'WA', 'Seattle', true, true, 'ongoing', false),
  ('ad000000-0000-4000-8000-000000000003', null, 'Seattle Animal Shelter', 'The City of Seattle municipal animal shelter, caring for lost, surrendered, and rescued animals with the help of community volunteers.', 'https://www.seattle.gov', 'https://www.google.com/s2/favicons?domain=www.seattle.gov&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'WA', 'Seattle', true, true, 'ongoing', false),
  ('ad000000-0000-4000-8000-000000000004', null, 'Seattle Parks and Recreation', 'The city department managing parks and recreation across Seattle, coordinating drop-in cleanup, restoration, and trail improvement events.', 'https://www.seattle.gov', 'https://www.google.com/s2/favicons?domain=www.seattle.gov&sz=128', 'environment', array['outdoors', 'family friendly'], false, false, 0, 'United States', 'WA', 'Seattle', true, true, 'both', false),
  ('ad000000-0000-4000-8000-000000000005', null, 'Green Seattle Partnership', 'A partnership restoring and maintaining Seattle forested parklands, relying on community volunteers for long-term forest health.', 'https://greenseattle.org', 'https://www.google.com/s2/favicons?domain=greenseattle.org&sz=128', 'environment', array['outdoors', 'family friendly', 'good for crews'], false, false, 0, 'United States', 'WA', 'Seattle', true, true, 'both', false),
  ('ad000000-0000-4000-8000-000000000006', null, 'King County Parks', 'The county parks department managing trails, natural areas, and parks across the greater Seattle region, with volunteer programs for all ages.', 'https://kingcounty.gov', 'https://www.google.com/s2/favicons?domain=kingcounty.gov&sz=128', 'environment', array['outdoors', 'family friendly'], false, false, 0, 'United States', 'WA', 'Seattle', true, true, 'both', false),
  ('ad000000-0000-4000-8000-000000000007', null, 'Seattle Parks Foundation', 'An independent nonprofit that champions and funds park improvements across Seattle, working alongside the city and community groups.', 'https://www.seattleparksfoundation.org', 'https://www.google.com/s2/favicons?domain=www.seattleparksfoundation.org&sz=128', 'environment', array['good for crews'], false, false, 0, 'United States', 'WA', 'Seattle', true, true, 'both', false),
  ('ad000000-0000-4000-8000-000000000008', null, 'Seattle Parks Coaching and Recreation', 'The recreation volunteer arm of Seattle Parks and Recreation, connecting volunteers to youth sports leagues and recreation program support.', 'https://seattle.gov', 'https://www.google.com/s2/favicons?domain=seattle.gov&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 14, 'United States', 'WA', 'Seattle', true, true, 'both', false),
  ('ad000000-0000-4000-8000-000000000009', null, 'Seattle Children''s Hospital', 'One of the top pediatric hospitals in the country, running a structured teen volunteer program supporting patients and hospital operations.', 'https://www.seattlechildrens.org', 'https://www.google.com/s2/favicons?domain=www.seattlechildrens.org&sz=128', 'medicine', array['counts for school hours', 'recurring'], false, false, 16, 'United States', 'WA', 'Seattle', true, true, 'ongoing', false),
  ('ad000000-0000-4000-8000-000000000010', null, 'UW Medicine', 'The academic medical system of the University of Washington, running a Summer Teen Program that exposes local high schoolers to healthcare careers.', 'https://www.uwmedicine.org', 'https://www.google.com/s2/favicons?domain=www.uwmedicine.org&sz=128', 'medicine', array['counts for school hours'], false, false, 16, 'United States', 'WA', 'Seattle', true, true, 'one-time', false),
  ('ad000000-0000-4000-8000-000000000011', null, 'Big Brothers Big Sisters of Puget Sound', 'A youth mentoring organization serving King, Pierce, Kitsap, Snohomish, and Island counties, matching adult volunteer mentors with kids ages 6 to 18.', 'https://inspirebig.org', 'https://www.google.com/s2/favicons?domain=inspirebig.org&sz=128', 'community', array['recurring', 'leadership role'], false, false, 18, 'United States', 'WA', 'Seattle', true, true, 'ongoing', false)
