insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('ae000000-0000-4000-8000-000000000001', 'ad000000-0000-4000-8000-000000000001', 'Volunteer with the Seattle Food Committee', 'food', 'Volunteers help sort, pack, and distribute food to Seattle residents facing food insecurity, with shifts posted regularly throughout the year. It is a straightforward, welcoming option if you want to get started with hunger relief in Seattle.', array['good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.seattlefoodcommittee.org/volunteer/', 'https://www.seattlefoodcommittee.org/volunteer/', '2026-01-01T00:00:00Z', 'Seattle', 'WA'),
  ('ae000000-0000-4000-8000-000000000002', 'ad000000-0000-4000-8000-000000000002', 'Join Seattle Humane Teen Programs', 'animals', 'Motivated 16-17 year-olds can apply for HSTP, a structured program combining animal welfare, community service, and career exploration, while students in grades 9-12 can also join High School Service Shifts for a small fee. It is a strong option if you want a real structured teen program rather than a casual shift.', array['recurring'], 16, false, false, true, '2-3 hrs', 'https://www.seattlehumane.org/get-involved/volunteer/', 'https://www.seattlehumane.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Seattle', 'WA'),
  ('ae000000-0000-4000-8000-000000000003', 'ad000000-0000-4000-8000-000000000003', 'Volunteer at the Seattle Animal Shelter', 'animals', 'Volunteer roles include Dog Walking, Cat Care, Administrative Support, Pet Food Bank, and Foster opportunities, giving you a choice of hands-on or behind-the-scenes work. It is a solid option if you want to pick the specific type of shelter role that fits you best.', array['recurring'], 16, false, false, true, '2-3 hrs', 'https://www.seattle.gov/animal-shelter/get-involved/volunteer', 'https://www.seattle.gov/animal-shelter/get-involved/volunteer', '2026-01-01T00:00:00Z', 'Seattle', 'WA'),
  ('ae000000-0000-4000-8000-000000000004', 'ad000000-0000-4000-8000-000000000004', 'Volunteer with Seattle Parks and Recreation', 'environment', 'Drop-in park cleanup, restoration, and trail improvement events run regularly across the city, and volunteers can also complete Scout project hours here. It is one of the easiest ways to find an outdoor project close to home anywhere in Seattle.', array['outdoors', 'family friendly'], 0, false, false, true, '2-3 hrs', 'https://www.seattle.gov/parks/volunteer', 'https://www.seattle.gov/parks/volunteer', '2026-01-01T00:00:00Z', 'Seattle', 'WA'),
  ('ae000000-0000-4000-8000-000000000005', 'ad000000-0000-4000-8000-000000000005', 'Volunteer with Green Seattle Partnership', 'environment', 'Volunteers help restore Seattle urban forests through invasive plant removal, native planting, and ongoing forest health work at parks across the city. It is a good pick if you specifically want to support long-term forest restoration rather than a single cleanup.', array['outdoors', 'family friendly', 'good for crews'], 0, false, false, true, '2-3 hrs', 'https://greenseattle.org/get-involved/volunteer/', 'https://greenseattle.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Seattle', 'WA'),
  ('ae000000-0000-4000-8000-000000000006', 'ad000000-0000-4000-8000-000000000006', 'Volunteer with King County Parks', 'environment', 'King County Parks offers hands-on service learning, environmental education, and even paid teen career pathway programs alongside its standard volunteer opportunities. It is a great option if you want to explore both volunteering and paid environmental career paths in one place.', array['outdoors', 'family friendly'], 0, false, false, true, '2-3 hrs', 'https://kingcounty.gov/en/dept/dnrp/nature-recreation/parks-recreation/king-county-parks/get-involved/volunteer', 'https://kingcounty.gov/en/dept/dnrp/nature-recreation/parks-recreation/king-county-parks/get-involved/volunteer', '2026-01-01T00:00:00Z', 'Seattle', 'WA'),
  ('ae000000-0000-4000-8000-000000000007', 'ad000000-0000-4000-8000-000000000007', 'Volunteer with Seattle Parks Foundation', 'environment', 'Volunteers support park improvement projects and community events that the Foundation champions across Seattle neighborhoods. It is a good complement to city-run park volunteering if you want to support advocacy and fundraising-adjacent projects too.', array['good for crews'], 0, false, false, true, 'Varies', 'https://www.seattleparksfoundation.org/get-involved/volunteer/', 'https://www.seattleparksfoundation.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Seattle', 'WA'),
  ('ae000000-0000-4000-8000-000000000008', 'ad000000-0000-4000-8000-000000000008', 'Coach or Volunteer with Seattle Parks Recreation', 'sports', 'Volunteers can coach youth sports leagues or support other recreation programs run by the city, giving you a chance to pass along skills from a sport you already know. It is a good fit if you want a recurring, active volunteer role.', array['recurring', 'leadership role'], 14, false, false, true, '1-2 hrs / week', 'https://seattle.gov/parks/volunteer/coaching-and-recreation', 'https://seattle.gov/parks/volunteer/coaching-and-recreation', '2026-01-01T00:00:00Z', 'Seattle', 'WA'),
  ('ae000000-0000-4000-8000-000000000009', 'ad000000-0000-4000-8000-000000000009', 'Volunteer at Seattle Children''s', 'medicine', 'Teen volunteers commit to at least one weekly three-hour shift, working toward a minimum of 60 hours of service, with applications opening each March, July, and November. It is a serious, structured option if you are considering pediatric healthcare as a career.', array['counts for school hours', 'recurring'], 16, false, false, true, '3 hrs / week', 'https://www.seattlechildrens.org/giving/volunteer/', 'https://www.seattlechildrens.org/giving/volunteer/', '2026-01-01T00:00:00Z', 'Seattle', 'WA'),
  ('ae000000-0000-4000-8000-000000000010', 'ad000000-0000-4000-8000-000000000010', 'Join the UW Medicine Summer Teen Program', 'medicine', 'The Summer Teen Program gives community high school students exposure to healthcare careers and hands-on service at UW Medicine facilities. It is a strong option if you want a university-affiliated medical volunteer experience.', array['counts for school hours'], 16, false, false, true, 'Summer program', 'https://www.uwmedicine.org/volunteering', 'https://www.uwmedicine.org/volunteering', '2026-01-01T00:00:00Z', 'Seattle', 'WA'),
  ('ae000000-0000-4000-8000-000000000011', 'ad000000-0000-4000-8000-000000000011', 'Become a Big with BBBS of Puget Sound', 'community', 'Volunteer mentors, called Bigs, are matched one-on-one with a Little for community-based, site-based, or group mentoring, connecting for at least four hours a month. Since mentors take on real ongoing responsibility for a young person, this program is best suited to older teens and adults.', array['recurring', 'leadership role'], 18, false, false, true, '4 hrs / month', 'https://inspirebig.org/', 'https://inspirebig.org/', '2026-01-01T00:00:00Z', 'Seattle', 'WA')
